SELECT o.order_id, o.auction_id, a.product_id, p.title AS product_title, p.thumbnail_url, o.seller_id, s.nickname AS seller_nickname, o.buyer_id, b.nickname AS buyer_nickname, o.final_price, o.status, o.payment_due, o.tracking_number, o.created_at FROM "order" o JOIN auction a ON a.auction_id = o.auction_id JOIN product p ON p.product_id = a.product_id JOIN member s ON s.member_id = o.seller_id JOIN member b ON b.member_id = o.buyer_id
o.buyer_id = #{memberId}
o.seller_id = #{memberId}
(o.buyer_id = #{memberId} OR o.seller_id = #{memberId})
AND o.status = #{status}::order_status
ORDER BY o.created_at DESC, o.order_id DESC

SELECT MAX(b.amount)
FROM bid b
WHERE b.auction_id = #{auctionId} AND b.member_id = #{memberId}
